class KeyBuffer {
public:
    // Append a printable character
    void AppendChar(wchar_t c) {
        std::lock_guard<std::mutex> lock(mtx_);
        buffer_.push_back(c);
    }

    // Append a named special key, e.g. "[ENTER]"
    void AppendToken(const std::wstring& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        buffer_ += token;
    }

    // Drain the buffer; returns everything accumulated so far
    std::wstring FlushKeyBuffer() {
        std::lock_guard<std::mutex> lock(mtx_);
        std::wstring out;
        out.swap(buffer_);          // efficient: buffer_ left empty
        return out;
    }

    size_t Size() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return buffer_.size();
    }

