// secure_file_crypt.cpp
// Encrypt/decrypt individual files with AES-256-GCM.
// Build (MSVC): cl /std:c++20 /EHsc /O2 secure_file_crypt.cpp

#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <fstream>
#include <vector>
#include <iostream>
#include <string>

static constexpr int KEY_LEN = 32;
static constexpr int IV_LEN  = 12;   // GCM standard
static constexpr int TAG_LEN = 16;

bool deriveKey(const std::string& passphrase,
               const std::vector<unsigned char>& salt,
               unsigned char* outKey) {
    return PKCS5_PBKDF2_HMAC(passphrase.c_str(), (int)passphrase.size(),
                             salt.data(), (int)salt.size(),
                             200000, EVP_sha256(), KEY_LEN, outKey) == 1;
}

bool cryptFile(const std::string& inPath, const std::string& outPath,
               const std::string& passphrase, bool encrypt) {
    std::ifstream in(inPath, std::ios::binary);
    if (!in) return false;
    std::vector<unsigned char> data((std::istreambuf_iterator<char>(in)),
                                     std::istreambuf_iterator<char>());

    unsigned char key[KEY_LEN];
    std::vector<unsigned char> salt(16), iv(IV_LEN);
    RAND_bytes(salt.data(), (int)salt.size());
    RAND_bytes(iv.data(), IV_LEN);
    deriveKey(passphrase, salt, key);

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER* cipher = EVP_aes_256_gcm();

    EVP_EncryptInit_ex(ctx, cipher, nullptr, nullptr, nullptr);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, IV_LEN, nullptr);
    EVP_EncryptInit_ex(ctx, cipher, nullptr, key, iv.data());

    std::vector<unsigned char> out(data.size());
    int len = 0, outLen = 0;
    EVP_EncryptUpdate(ctx, out.data(), &len, data.data(), (int)data.size());
    outLen = len;

    unsigned char tag[TAG_LEN];
    EVP_EncryptFinal_ex(ctx, out.data() + outLen, &len);
    outLen += len;
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, TAG_LEN, tag);
    EVP_CIPHER_CTX_free(ctx);

    std::ofstream f(outPath, std::ios::binary);
    f.write((char*)salt.data(), salt.size());
    f.write((char*)iv.data(), iv.size());
    f.write((char*)tag, TAG_LEN);
    f.write((char*)out.data(), outLen);
    return true;
}
